<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Pointly POS | Sales History</title><?= view('partials/styles') ?></head><body><div class="app-shell"><?= view('partials/nav', ['active' => 'sales']) ?><main class="content"><header class="topbar"><div><p class="eyebrow">Transactions</p><h1>Sales history</h1><p class="subtitle">Review completed sales recorded by POS staff.</p></div><div class="profile"><div class="avatar">AD</div> Admin account</div></header><section class="panel"><div class="panel-heading"><div><h2>Transaction history</h2><span><?= count($sales) ?> records found</span></div><a class="button" href="<?= base_url('sales/new') ?>">Record sale +</a></div><?php if (session()->getFlashdata('success')): ?><div class="form-error" style="background:#e7faf7;color:#0f9488"><?= esc(session()->getFlashdata('success')) ?></div><?php endif; ?><div class="table-wrap"><table><thead><tr><th>Product</th><th>Customer</th><th>Staff member</th><th>Quantity</th><th>Total price</th><th>Date</th></tr></thead><tbody><?php if (!empty($sales)): ?><?php foreach ($sales as $sale): ?><tr><td><div class="person"><span class="person-avatar">▣</span><?= esc($sale['product_name']) ?></div></td><td><?= esc($sale['customer_name'] ?? 'Walk-in customer') ?></td><td><?= esc($sale['staff_name']) ?></td><td><?= esc($sale['quantity']) ?></td><td>₱<?= number_format((float) $sale['total_price'], 2) ?></td><td><?= esc($sale['created_at']) ?></td></tr><?php endforeach; ?><?php else: ?><tr><td colspan="6">No sales recorded yet.</td></tr><?php endif; ?></tbody></table></div></section></main></div></body></html>
